INSERT INTO feature VALUES('value-crossing','runtime','A run''s values crossing worlds by content','runtime-lam','partial','notable',NULL,'A value a store binds commits to the content-addressed value plane and derefs into another store at addresses fresh there: a literal of every kind, and a tuple, record, list, injection, lift or datatype''s constructor over crossing fields, a family as its declaration''s index. A value shared twice crosses unfolded and derefs as a tree, a pair shared at twenty levels writing 7,340,029 records into 5 chunks; a thunk crosses as its body''s command and its captures, and the run it lands in lays it out at its own site for that body; a closure, stack, code, capability, opaque constant or session record is refused by name with nothing written, and a payload the codec does not write refuses its constructor. A value of an unmarked sealed type, a secret among them (secret-never-open), is refused `Immobile` at check time, before it reaches the codec. A migration''s captures and answer cross through it (world-migration), between processes too (migrate-wire); a family named by content across processes is owed (#3293).','runtime-emitter','crates/runtime-emitter/tests/crossing.rs corpus/pathological/worlds/secret-crosses.gandr','crate-tests','#3293');
